def yrs(a):   # birth years of the sign from 1936 to 2027, with the date each year starts (as horoscope-2027.py)
    base = 1936 + (A.index(a) - A.index("Rat")) % 12
    out = []
    for y in range(base, 2028, 12):
        md = CNY[y]; m, d = int(md[:2]), int(md[3:])
        out.append((y, (d, m, y), ELEM[y % 10]))
    return out


def verify(a, en, years, nums):
    """the tables and numbers must be the ones of the English spec"""
    h1, h4 = en["sections"][1]["html"], en["sections"][4]["html"]
    rows = re.findall(r'<tr><th scope="row">(\d+)</th><td>(\d+) (\w+) (\d+)</td><td>(\w+) \w+</td>', h1)
    assert rows == [(str(y), str(d[0]), MONTHS[d[1] - 1], str(y), el) for y, d, el in years], f"{a}: year table differs from the English spec"
    mrows = re.findall(r'<tr><th scope="row">(\w+)</th><td>([^<]*)</td>', h4)
    assert mrows == [(m, f"{en_d(f)} – {en_d(to)}") for m, f, to in ZMONTHS], f"{a}: month table differs from the English spec"
    assert en["facts"][2][1] == nums, f"{a}: lucky numbers differ from the English spec"
    info = AI[a]
    cols = [KCOL[c] for c in info["luckyColors"]]; days = [KDAY[d] for d in info["luckyDays"]]
    if cols != KAI[a]["luckyColors"]: print(f"  note: {a} lucky colors in KM_ANIMAL_INFO {KAI[a]['luckyColors']} differ from the English {info['luckyColors']}; using the English")
    if days != KAI[a]["luckyDays"]: print(f"  note: {a} lucky days in KM_ANIMAL_INFO {KAI[a]['luckyDays']} differ from the English {info['luckyDays']}; using the English")
    return cols, days


def page(a, en):
    s = a.lower(); n = KN[a]; info = AI[a]; rel = REL.get(a, "neutral"); t = T[a]
    mates = [x for x in tri(a) if x != a]; opp = clash(a)
    nums = ", ".join(str(x) for x in info["luckyNumbers"])
    years = yrs(a)
    kcols, kdays = verify(a, en, years, nums)
    cols = " ".join(kcols); days = " និង".join(kdays)
    trow = "".join(f'<tr><th scope="row">{y}</th><td>{dmy(d)}</td><td>{n} ធាតុ{KE[el]}</td>'
                   f'<td>{"កើតក្នុងឆ្នាំ 2027" if y == 2027 else f"អាយុគ្រប់ {2027 - y} ឆ្នាំ"}</td><td>{WITH_FIRE[el]}</td></tr>' for y, d, el in years)
    ytable = ('<div class="table-wrap"><table class="data"><thead><tr><th scope="col">ឆ្នាំកំណើត</th><th scope="col">ថ្ងៃចាប់ផ្ដើមឆ្នាំ</th><th scope="col">ធាតុ</th>'
              '<th scope="col">ក្នុងឆ្នាំ 2027</th><th scope="col">ធាតុរបស់អ្នក និងភ្លើងនៃឆ្នាំ</th></tr></thead><tbody>' + trow + "</tbody></table></div>")
    def mark(m):
        if m == a: return "<strong>ខែរាសីខ្លួនឯង</strong>"
        if m in mates: return "<strong>ខែត្រីកោណ</strong>៖ តាមប្រពៃណី រលូនជាង"
        if m == opp: return "<strong>ខែប៉ះទង្គិច</strong>៖ គួរប្រុងប្រយ័ត្នជាងធម្មតា"
        return ""
    mrow = "".join(f'<tr><th scope="row">ខែ{KN[m]}</th><td>{rng(f, to)}</td><td>{mark(m)}</td></tr>' for m, f, to in ZMONTHS)
    mtable = ('<div class="table-wrap"><table class="data narrow"><thead><tr><th scope="col">ខែ</th><th scope="col">កាលបរិច្ឆេទឆ្នាំ 2027</th>'
              f'<th scope="col">សម្រាប់រាសី{n}</th></tr></thead><tbody>' + mrow + "</tbody></table></div>")
